insert into negocios (id, nombre, slug, categoria_oficial_id, municipio, vereda_id, direccion, latitud, longitud, descripcion_corta, descripcion, producto, telefono, whatsapp, email, representante_legal, nit, naturaleza_juridica, delegado, tiempo_constitucion, rut_camara_comercio, responsable_cdmb, novedad, tipo_negocio_verde, codigo_marca, anio_registro, cota_msnm, este, norte, aplicacion_ficha_2025, observaciones, registro_nacional_turismo, uso_suelo, concesion_aguas, concesion_aguas_vencimiento, vertimientos, vertimientos_vencimiento, pueaa, pgris, pozo_septico, alcantarillado, ica, ica_vencimiento, invima, invima_vencimiento, certificado_tenencia_animales, buenas_practicas_agricolas, buenas_practicas_apicolas, registro_apicola, intervencion_cauce, capacidad_carga, sstt, canal_venta, exportacion, huella_carbono, fortalecimiento_tecnico, fortalecimiento_academico, fortalecimiento_financiero, internacionalizacion, certificaciones, posicionamiento_marca, beneficios_ventanilla, fortalezas_ambiental, fortalezas_social, fortalezas_economico, debilidades_ambiental, debilidades_social, debilidades_financiera, emprendimiento_verde, sello_marca, avalado, destacado, activo) values ('486189f3-fe7c-42c6-a324-66fdb510b4b1', 'LA NIEBLA', generar_slug_unico('LA NIEBLA', '486189f3-fe7c-42c6-a324-66fdb510b4b1'), (select id from categorias_oficiales where slug = 'bioproductos-servicios-sostenibles'), 'Bucaramanga', (select id from veredas where municipio = 'Bucaramanga' and slug = 'san-jose'), 'ALTO DE LOS PADRES VEREDA SAN JOSE- CORREGIMIENTO 3 FINCA LA NIEBLA', 7.12418, -73.07998, 'El restaurante la Niebla se enfoca en dar a concocer la gastronomía local a través de sus platos fuertes carnes, pescados y dentro de sus instalaciones hay…', 'El restaurante la Niebla se enfoca en dar a concocer la gastronomía local a través de sus platos fuertes carnes, pescados y dentro de sus instalaciones hay un sendero llamado Bosque de Niebla el cual permite  que el visitante se pueda conectar con el medio natural llevandose una experiencia de bienestar y salud. En cuanto al tema gastronomico se están implementando huertas ecologicas de hortalizas , cafe organico entre otros para consumo del mismo restaurante. La población objetivo son familias, empresas e instituciones educativas.', 'GASTRONÓMICO', '3103248309 - 3124090107', '3103248309 - 3124090107', 'jmgpuyana@hotmail.com', 'JUAN MANUEL GONZALEZ PUYANA', '5563651-9', 'Natural', null, '251 MESES', 'CÁMARA DE COMERCIO Y RUT', 'DIEGO GUTIERREZ', 'RETIRADO', 'Satisfactorio', null, 2022, '1.645 msnm', '73.07998', '7.12418', 'NO ACTUALIZO', 'No se realizo visita ni se aplico ficha de verificacion', 'NO', null, null, null, 'REQUIERE', null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, 'NO', 'B2B', null, null, 'Servicio al cliente, estandarización de procesos, marketing, bilinguismo, manipulación de alimentos, buenas prácticas.', null, 'Contabilidad, costos, manejo de proveedores.', null, null, 'OTAS como booking, redes sociales, fortalecimiento de reputación online (google my business', null, 'Contribuye a la biodiversidad conservando flora y fauna local en el bosque de niebla. Regulación hídrica. Mantiene la calidad y eficiencia del agua gracias a la regulación hídrica del bosque. Reduce gases de efecto invernadero con gran cantidad de árboles. Disminuye emisiones y mejora la salud con alimentos naturales de huerta propia. Sensibiliza sobre agroindustria sostenible y agroturismo.', 'Espacios agradables: Entorno natural que facilita un ambiente relajado para tareas diarias. Actividades lúdicas y alimentación fomentan un ambiente laboral de calidad. Promueve la economía local generando empleo para la comunidad campesina. Pagos justos y a tiempo optimizan el trabajo y satisfacción laboral.', 'Decisiones rápidas en precios y promociones mejoran la eficiencia operativa. Costos operativos bajos aumentan larentabilidad  del restaurante.', 'Requiere gestión de residuos inorgánicos por alta generación. Necesita energías alternativas para reducir consumo excesivo. Dificulta garantizar condiciones aceptables de agua residual para riego. Dificulta garantizar condiciones aceptables de agua residual para riego. Puede causar erosión y daño al ecosistema por alta afluencia en el sendero.  El ruido puede deteriorar y migrar la fauna local.', 'Actividades de campo causan desgaste físico y alta rotación de personal. Actividades repetitivas desmotivan y aumentan la rotación de personal. Necesidad de programas de salud y seguridad en el trabajo.', 'Sistema financiero débil dificulta el seguimiento de ventas e inventarios. Problemas de precios afectan la rentabilidad y competitividad en el mercado. Costos laborales altos reducen la rentabilidad en tiempos de baja demanda.', true, false, false, false, false);
